    for line in lines:
        match = re.match(r"Object (\d+): (.+?) \(color=.+?, material=.+?, shape=.+?\)", line)
        if match:
            obj_id = match.group(1)
            desc = match.group(2)
            objects.append({"id": obj_id, "description": desc})
    return objects


def _parse_events_list(lines):
    """Parse Events list lines into structured event dicts."""
    events = []
    for line_idx, line in enumerate(lines):
        frame_match = re.match(r"Frame (\d+):", line)
        if not frame_match:
            continue
        frame = int(frame_match.group(1))

        collision_match = re.search(r"Object (\d+).+?collides with Object (\d+)", line)
        if collision_match:
            events.append({
                "frame": frame,
                "type": "collision",
                "entities": [collision_match.group(1), collision_match.group(2)],
                "index": line_idx,
            })
            continue

        exit_match = re.search(r"Object (\d+).+?exits the scene", line)
        if exit_match:
            events.append({
                "frame": frame,
                "type": "exit",
                "entities": [exit_match.group(1)],
                "index": line_idx,
            })
            continue

        enters_match = re.search(r"Object (\d+).+?enters the scene", line)
        if enters_match:
            events.append({
                "frame": frame,
                "type": "enters",
                "entities": [enters_match.group(1)],
                "index": line_idx,
            })
            continue

        in_view_match = re.search(r"Object (\d+).+?is in view when the video begins", line)
        if in_view_match:
            events.append({
                "frame": frame,
                "type": "in_view_beginning",
                "entities": [in_view_match.group(1)],
                "index": line_idx,
            })
            continue
    return events


