import re

def _parse_objects_list(lines):
    objects = []
    for line in lines:
        match = re.match(r"Object (\d+): (.+?) \(color=.+?, material=.+?, shape=.+?\)", line)
        if match:
            objects.append({"id": match.group(1), "description": match.group(2)})
    return objects

def _parse_events_list(lines):
    events = []
    for line_idx, line in enumerate(lines):
        frame_match = re.match(r"Frame (\d+):", line)
        if not frame_match:
            continue
        frame = int(frame_match.group(1))

        if "collides with" in line:
            m = re.search(r"Object (\d+).+?collides with Object (\d+)", line)
            if m:
                events.append({"frame": frame, "type": "collision", "entities": [m.group(1), m.group(2)], "index": line_idx})
        elif "exits the scene" in line:
            m = re.search(r"Object (\d+).+?exits the scene", line)
            if m:
                events.append({"frame": frame, "type": "exit", "entities": [m.group(1)], "index": line_idx})
        elif "enters the scene" in line:
            m = re.search(r"Object (\d+).+?enters the scene", line)
            if m:
                events.append({"frame": frame, "type": "enters", "entities": [m.group(1)], "index": line_idx})
        elif "is in view when the video begins" in line:
            m = re.search(r"Object (\d+).+?is in view when the video begins", line)
            if m:
                events.append({"frame": frame, "type": "in_view_beginning", "entities": [m.group(1)], "index": line_idx})
    return events

def _find_child(doc, scope_node, title_pattern):
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child["title"].startswith(title_pattern):
            return child
    return None

def entities(doc, scope):
    video_num = scope.replace("Video ", "")
    scope_node = node_by_title(doc, scope)
    objects_node = _find_child(doc, scope_node, f"Video {video_num}: Objects")
    if objects_node is None:
        return []
    return _parse_objects_list(objects_node.get("lines", []))

