import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # Constants derived from analyzing recorded data
    DT = 0.025        # seconds per frame (position = velocity * DT)
    FRICTION = 0.01   # velocity decay factor per frame
    COLLISION_THRESHOLD = 0.45
    RESTITUTION = 0.5
    COOLDOWN = 2      # min frames between same-pair collisions

    # Get motion log data
    video_num = scope.replace("Video ", "")
    scope_node = node_by_title(doc, scope)
    motion_node = _find_child(doc, scope_node, f"Video {video_num}: Motion log")

    motion_data = {}  # (obj_id, frame) -> {x, y, vx, vy}
    if motion_node is not None:
        for ridx, cells in table_rows(motion_node):
            frame = int(cells["frame"])
            obj_id = cells["object"].split()[0]
            motion_data[(obj_id, frame)] = {
                "x": float(cells["x"]),
                "y": float(cells["y"]),
                "vx": float(cells["vx"]),
                "vy": float(cells["vy"])
            }

    # Initialize state from inputs
    state = {}  # obj_id -> {x, y, vx, vy, active, entered}
    for inp in inputs:
        obj_id = inp["entities"][0]
        if inp["kind"] == "in_view_beginning":
            state[obj_id] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"],
                "active": True,
                "entered": 0.0
            }
        elif inp["kind"] == "enters":
            state[obj_id] = {
                "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0,
                "active": False,
                "entered": inp["time"]
            }

    # If start > 0, update state to start using motion log
    if start > 0 and motion_node is not None:
        start_frame = int(start)
        for obj_id, s in state.items():
            # Skip objects that haven't entered yet
            if not s["active"] and s["entered"] > start:
                continue
            # Find latest motion record at or before start
            best = None
            for (oid, frame), data in motion_data.items():
                if oid == obj_id and frame <= start_frame:
                    if best is None or frame > best[0]:
                        best = (frame, data)
            if best is not None:
                frame, md = best
                dt = start - frame  # frames to advance
                s["x"] = md["x"] + md["vx"] * DT * dt
                s["y"] = md["y"] + md["vy"] * DT * dt
                s["vx"] = md["vx"] * (1 - FRICTION) ** dt
                s["vy"] = md["vy"] * (1 - FRICTION) ** dt
                s["active"] = True

    outcomes = []
    last_collision = {}  # pair -> last collision time

    t = start
    while t < horizon:
        # Activate entering objects
        for obj_id, s in state.items():
            if not s["active"] and s["entered"] <= t:
                entry_frame = int(s["entered"])
                if (obj_id, entry_frame) in motion_data:
                    md = motion_data[(obj_id, entry_frame)]
                    s["x"] = md["x"]
                    s["y"] = md["y"]
                    s["vx"] = md["vx"]
                    s["vy"] = md["vy"]
                s["active"] = True

        active = [(oid, s) for oid, s in state.items() if s["active"]]

        # Update positions and apply friction
        for oid, s in active:
            speed = math.sqrt(s["vx"]**2 + s["vy"]**2)
            if speed > stationary_threshold:
                s["x"] += s["vx"] * DT
                s["y"] += s["vy"] * DT
                s["vx"] *= (1 - FRICTION)
                s["vy"] *= (1 - FRICTION)
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for collisions
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                oid1, s1 = active[i]
                oid2, s2 = active[j]

                pair = tuple(sorted([oid1, oid2], key=lambda x: int(x)))
                if pair in last_collision and t - last_collision[pair] < COOLDOWN:
                    continue

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < COLLISION_THRESHOLD and dist > 0.01:
                    nx = dx / dist
                    ny = dy / dist
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:  # objects are approaching
                        # Elastic collision with restitution
                        s1["vx"] -= (1 + RESTITUTION) * dvn * nx
                        s1["vy"] -= (1 + RESTITUTION) * dvn * ny
                        s2["vx"] += (1 + RESTITUTION) * dvn * nx
                        s2["vy"] += (1 + RESTITUTION) * dvn * ny

                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })
                        last_collision[pair] = t

        t += 1

    return outcomes
